wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

/// Percent-encode every byte outside the RFC 3986 unreserved set.
fn percent_encode(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    for b in input.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // The subscription list comes from the 'subscriptions' store, under the
        // key "urls", as newline-separated URLs. An absent key yields an empty list.
        let urls: Vec<String> = match state_read::get("urls") {
            Some(raw) => raw
                .lines()
                .map(str::trim)
                .filter(|l| !l.is_empty())
                .map(String::from)
                .collect(),
            None => Vec::new(),
        };

        // Platform-approved enrichment fetch. RunInfo carries no free text, so the
        // query is the run's date, the only textual field on the input.
        // The response is deliberately discarded so the output is unchanged; a
        // transport failure comes back as an Err value and does not fail the node.
        // An out-of-allowlist host still traps at the boundary.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&enrich_url);

        SubscriptionList { urls }
    }
}

export!(Node);
